async function main(): Promise<void> {
  const g: any = (globalThis as any);
  g.__lit = { list: [1, 2, 3], names: ["a", "b"] };
  const o: any = g.__lit;
  const a = o.list.map((x: any) => x);
  console.log(JSON.stringify(a), a.length);
  const b = o.names.map((s: any) => s);
  console.log(JSON.stringify(b));
  const c = JSON.parse('{"xs":[4,5,6]}').xs.map((x: any) => x);
  console.log(JSON.stringify(c));
  const d: any = [{ xs: [1, 2] }];
  console.log(JSON.stringify(d[0].xs.map((x: any) => x)));
}
